export function getFoodRecommendation(rvLevel) {
    const level = Math.min(Math.max(Number(rvLevel) || 2, 2), 20);
    return FOOD_RECOMMENDATIONS_BY_RV[level] || FOOD_RECOMMENDATIONS_BY_RV[2];
}
